<?php
/**
 * Apple identity verification and native token login.
 *
 * @package ExtraChill\Users\OAuth
 */

defined( 'ABSPATH' ) || exit;

/**
 * Verify an Apple identity token, including the SHA-256 native nonce.
 *
 * @param string $identity_token Signed Apple JWT.
 * @param string $raw_nonce      Original, unhashed nonce generated by the client.
 * @return array|WP_Error Verified identity or generic authentication error.
 */
function ec_verify_apple_token( string $identity_token, string $raw_nonce ) {
	$audiences = function_exists( 'ec_get_apple_audiences' )
		? ec_get_apple_audiences()
		: array_filter( array(
			get_site_option( 'extrachill_apple_bundle_id', '' ),
			get_site_option( 'extrachill_apple_client_id', '' ),
		) );

	if ( empty( $audiences ) || ( function_exists( 'ec_is_apple_oauth_configured' ) && ! ec_is_apple_oauth_configured() ) ) {
		return new WP_Error( 'apple_not_configured', 'Apple Sign-In is not configured.', array( 'status' => 500 ) );
	}

	$payload = ec_verify_rs256_jwt( $identity_token, 'https://appleid.apple.com/auth/keys', $audiences, 'https://appleid.apple.com' );
	$reason  = '';
	if ( is_wp_error( $payload ) ) {
		$reason = $payload->get_error_message();
	} elseif ( '' === $raw_nonce || ! isset( $payload['nonce'] ) || ! is_string( $payload['nonce'] )
		|| ! hash_equals( hash( 'sha256', $raw_nonce ), $payload['nonce'] ) ) {
		$reason = 'Missing or mismatched nonce.';
	} elseif ( empty( $payload['sub'] ) || ! is_string( $payload['sub'] ) ) {
		$reason = 'Missing subject identifier.';
	}

	if ( '' !== $reason ) {
		// phpcs:ignore WordPress.PHP.DevelopmentFunctions.error_log_error_log -- Operational OAuth failure logging, without token contents.
		error_log( 'Apple token verification failed: ' . $reason );
		return new WP_Error( 'invalid_apple_token', 'Apple sign-in failed. Please try again.', array( 'status' => 401 ) );
	}

	return array(
		'apple_id'         => $payload['sub'],
		'email'            => isset( $payload['email'] ) && is_string( $payload['email'] ) ? $payload['email'] : '',
		'email_verified'   => isset( $payload['email_verified'] ) && in_array( $payload['email_verified'], array( true, 'true' ), true ),
		'is_private_email' => isset( $payload['is_private_email'] ) && in_array( $payload['is_private_email'], array( true, 'true' ), true ),
	);
}

/**
 * Resolve a verified Apple identity. Unsigned profile names are creation-only.
 *
 * @param array $apple_user        Verified Apple identity.
 * @param array $profile           Optional given_name and family_name.
 * @param array $registration_data Registration attribution.
 * @return array|WP_Error Resolved account.
 */
function ec_oauth_apple_user( array $apple_user, array $profile, array $registration_data ) {
	$apple_id = isset( $apple_user['apple_id'] ) ? sanitize_text_field( $apple_user['apple_id'] ) : '';
	if ( '' === $apple_id ) {
		return new WP_Error( 'missing_apple_data', 'Missing Apple user data.', array( 'status' => 400 ) );
	}

	$user = ec_get_user_by_apple_id( $apple_id );
	if ( $user ) {
		return array(
			'user_id' => (int) $user->ID,
			'is_new'  => false,
			'user'    => $user,
		);
	}

	$email = isset( $apple_user['email'] ) ? sanitize_email( $apple_user['email'] ) : '';
	if ( '' === $email ) {
		return new WP_Error( 'missing_apple_email', 'Apple did not provide an email address. Please authorize email sharing with Apple and try again.', array( 'status' => 400 ) );
	}
	$verified = isset( $apple_user['email_verified'] ) && in_array( $apple_user['email_verified'], array( true, 'true' ), true );
	if ( ! $verified ) {
		return new WP_Error( 'email_not_verified', 'Apple sign-in failed. Please try again.', array( 'status' => 401 ) );
	}

	$user = get_user_by( 'email', $email );
	if ( $user ) {
		// Apple has cryptographically attested control of this verified email,
		// including private-relay addresses. Sites may require explicit linking.
		if ( ! apply_filters( 'ec_apple_auto_link_verified_email', true, $email, $apple_id ) ) {
			return new WP_Error( 'account_exists_unlinked', 'An account with this email already exists. Please log in with your password to link your Apple account.', array( 'status' => 409 ) );
		}
		ec_link_apple_account( (int) $user->ID, $apple_id );
		do_action( 'ec_apple_account_linked', (int) $user->ID, $apple_id, $email );
		return array(
			'user_id'         => (int) $user->ID,
			'is_new'          => false,
			'user'            => $user,
			'linked_existing' => true,
		);
	}

	$name     = trim( sanitize_text_field( $profile['given_name'] ?? '' ) . ' ' . sanitize_text_field( $profile['family_name'] ?? '' ) );
	$username = function_exists( 'ec_generate_username_from_name' ) && '' !== $name
		? ec_generate_username_from_name( $name )
		: ( function_exists( 'ec_generate_username_from_email' ) ? ec_generate_username_from_email( $email ) : 'user' . wp_rand( 10000, 99999 ) );
	// Identity fields cannot be overridden by registration attribution or profile.
	$data    = array_merge( array_filter( $registration_data ), array(
		'username'  => $username,
		'password'  => wp_generate_password( 24, true, true ),
		'email'     => $email,
		'from_join' => false,
	) );
	$user_id = apply_filters( 'extrachill_create_community_user', false, $data );
	if ( is_wp_error( $user_id ) || empty( $user_id ) ) {
		return new WP_Error( 'user_creation_failed', 'Failed to create user account.', array( 'status' => 500 ) );
	}
	ec_link_apple_account( (int) $user_id, $apple_id );
	if ( '' !== $name ) {
		wp_update_user( array(
			'ID'           => (int) $user_id,
			'display_name' => $name,
		) );
	}
	$user = get_user_by( 'id', (int) $user_id );
	if ( ! $user ) {
		return new WP_Error( 'user_not_found', 'User not found after creation.', array( 'status' => 500 ) );
	}
	return array(
		'user_id' => (int) $user_id,
		'is_new'  => true,
		'user'    => $user,
	);
}

/** Link an Apple subject to a WordPress account. */
function ec_link_apple_account( $user_id, $apple_id ) {
	$user_id  = absint( $user_id );
	$apple_id = sanitize_text_field( $apple_id );
	if ( ! $user_id || '' === $apple_id ) {
		return false;
	}
	update_user_meta( $user_id, 'apple_user_id', $apple_id );
	update_user_meta( $user_id, 'oauth_linked_at', time() );
	return true;
}

/** Find an account by its Apple subject, not its unsigned profile. */
function ec_get_user_by_apple_id( $apple_id ) {
	$apple_id = sanitize_text_field( $apple_id );
	if ( '' === $apple_id ) {
		return false;
	}
	$users = get_users( array(
		'meta_key'   => 'apple_user_id',
		'meta_value' => $apple_id,
		'number'     => 1,
	) );
	return ! empty( $users ) ? $users[0] : false;
}

/**
 * Native Apple login. Browser cookies and client redirects are not supported.
 *
 * @param string $identity_token Apple identity JWT.
 * @param string $device_id      UUIDv4 device identifier.
 * @param array  $options        Nonce, profile, device and registration metadata.
 * @return array|WP_Error Standard native token response.
 */
function ec_apple_login_with_tokens( string $identity_token, string $device_id, array $options ) {
	if ( empty( $device_id ) || ! extrachill_users_is_uuid_v4( $device_id ) ) {
		return new WP_Error( 'invalid_device_id', 'device_id must be a UUID v4.', array( 'status' => 400 ) );
	}
	$identity = ec_verify_apple_token( $identity_token, isset( $options['raw_nonce'] ) ? (string) $options['raw_nonce'] : '' );
	if ( is_wp_error( $identity ) ) {
		return $identity;
	}
	$registration_data = array(
		'registration_source' => ! empty( $options['registration_source'] ) ? sanitize_text_field( (string) $options['registration_source'] ) : 'web',
		'registration_method' => ! empty( $options['registration_method'] ) ? sanitize_text_field( (string) $options['registration_method'] ) : 'apple',
		'registration_page'   => isset( $options['registration_page'] ) ? esc_url_raw( (string) $options['registration_page'] ) : '',
	);
	$result            = ec_oauth_apple_user( $identity, $options, $registration_data );
	if ( is_wp_error( $result ) ) {
		return $result;
	}
	$native_options = array(
		'device_name'         => $options['device_name'] ?? '',
		'newsletter_consent'  => ! empty( $options['newsletter_consent'] ),
		'registration_method' => $registration_data['registration_method'],
	);
	return ec_oauth_complete_token_login( $result, $device_id, $native_options, $registration_data );
}
